get("apiYn")) !== 'Y'); } }, { id: "if_listProcsStatCd", grids: ["grd_formFileList"], fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listProcsStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listProcsStatCd")) === ''); } }, { id: "if_useYn_2", fn: function(){ return ((dlt_attachList.getCellData(0, "useYn") ?? (() => { throw new Error("unresolved:" + "ent.useYn"); })())==='Y'); } }, { id: "if_fileSeq_2", fn: function(){ return ((dlt_formFileList.getCellData(0, "fileSeq") ?? (() => { throw new Error("unresolved:" + "entity.fileSeq"); })()) === (dlt_attachList.getCellData(0, "attachFileSeq") ?? (() => { throw new Error("unresolved:" + "ent.attachFileSeq"); })())); } }, { id: "docuItem_2_2", fn: function(){ return ((dlt_formFileList.getCellData(0, "fileSeq") ?? (() => { throw new Error("unresolved:" + "entity.fileSeq"); })()) === (dlt_attachList.getCellData(0, "attachFileSeq") ?? (() => { throw new Error("unresolved:" + "ent.attachFileSeq"); })())); } }, { id: "if_requiredYn_4", fn: function(){ return ((dlt_formFileList.getCellData(0, "requiredYn") ?? (() => { throw new Error("unresolved:" + "entity.requiredYn"); })()) === 'N'); } }, { id: "docuItem_2_2", fn: function(){ return ((dlt_formFileList.getCellData(0, "requiredYn") ?? (() => { throw new Error("unresolved:" + "entity.requiredYn"); })()) === 'N'); } }, { id: "if_apiYn_4", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "apiYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("apiYn")) === 'Y'); } }, { id: "tr_248", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "apiYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("apiYn")) === 'Y'); } }, { id: "docuItem_2_3", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "apiYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("apiYn")) === 'Y'); } }, { id: "if_apiYn_5", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "apiYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("apiYn")) !== 'Y'); } }, { id: "tr_270", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "apiYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("apiYn")) !== 'Y'); } }, { id: "docuItem_3_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "apiYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("apiYn")) !== 'Y'); } }, { id: "if_listProcsStatCd_2", grids: ["grd_formFileList_3"], fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listProcsStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listProcsStatCd")) !== ''); } }, { id: "btn_doSave", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listProcsStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listProcsStatCd")) === '' || ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listProcsStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listProcsStatCd")) === '30' || ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listProcsStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listProcsStatCd")) === '35' || ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listProcsStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listProcsStatCd")) === '37'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
