            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_110", entity: "dlt_formFileList", countIds: [], cells: [{ childId: "__rc5", fn: function (v, i) { return String(i + 1) + "."; } }, { childId: "ipt_fileItmNm_2", fn: function (v, i) { return String(v("fileItmNm")); } }] },
        { genId: "c_foreach_225", entity: "dlt_attachList", countIds: [], cells: [{ childId: "__rc12", fn: function (v, i) { return String(i + 1) + "."; } }, { childId: "ipt_remk_6", fn: function (v, i) { return String(v("remk")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_bzProcsNo", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("bzProcsNo"))); } },
        { childId: "ipt_fileItmNm_3", fn: function () { return String(dlt_attachList.getCellData(60100, "attach_file_itm_nm")); } },
        { childId: "__rb6", fn: function () { return String(dlt_attachList.getCellData(60100, "attach_file_itm_nm")); } },
        { childId: "ipt_fileItmNm_3_r1", fn: function () { return String(dlt_attachList.getCellData(60200, "attach_file_itm_nm")); } },
        { childId: "__rb7", fn: function () { return String(dlt_attachList.getCellData(60200, "attach_file_itm_nm")); } },
        { childId: "ipt_fileItmNm_3_r2", fn: function () { return String(dlt_attachList.getCellData(60300, "attach_file_itm_nm")); } },
        { childId: "__rb8", fn: function () { return String(dlt_attachList.getCellData(60300, "attach_file_itm_nm")); } },
        { childId: "ipt_fileItmNm_3_r3", fn: function () { return String(dlt_attachList.getCellData(60400, "attach_file_itm_nm")); } },
        { childId: "__rb9", fn: function () { return String(dlt_attachList.getCellData(60400, "attach_file_itm_nm")); } },
        { childId: "ipt_fileItmNm_3_r4", fn: function () { return String(dlt_attachList.getCellData(60500, "attach_file_itm_nm")); } },
        { childId: "__rb10", fn: function () { return String(dlt_attachList.getCellData(60500, "attach_file_itm_nm")); } },
        { childId: "ipt_bzProcsNo_2", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("bzProcsNo"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        form = (document.preListForm || { elements: [] });
        scwin.setEditMode(null);
        await scwin.checkSave();
        $(':file').change(async function() {
                const id = $(this).attr('id');
                const vfile = $('#' + id)[0].files[0];
                const val = $('#' + id)[0].value;
                if (vfile != null) {
                    if (vfile.size == 0) {
                        await $c.win.alert('0byte파일은 첨부할 수 없습니다.');
                        $(this).val("");
                    }
                    const chkFileSize = vfile.size;
                    let mSize = 20;
                    if (id.indexOf("Api") > -1) {
                        mSize = 100;
                    }
                    if (chkFileSize > mSize * (1024 * 1024)) {
                        await $c.win.alert('첨부파일의 용량은 개당 ' + mSize + 'MB를 넘을 수 없습니다.');
                        $(this).val("");
                    }
                    const fVal = val.split("\\");
                    const fNm = fVal[fVal.length - 1];
                    if (scwin.calBytes(fNm) > 80) {
                        await $c.win.alert('파일명이 너무 길면 첨부할 수 없습니다.');
                        $(this).val("");
                    }
                    const isFileType = new Array("bmp", "gif", "jpeg", "jpg", "png", "hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "zip", "txt");
                    const fileType = val.substring(val.lastIndexOf(".") + 1).toLowerCase();
                    let typeChkCnt = 0;
                    for (i = 0; i < isFileType.length; i++) {
                        if (isFileType[i] === fileType) {
                            typeChkCnt++;
                        }
                    }
                    if (typeChkCnt == 0) {
                        await $c.win.alert('첨부할 수 없는 확장자입니다.\n사용가능 확장자 : bmp, gif, jpeg, jpg, png, hwp, docx, doc, xls, xlsx, ppt, pptx, pdf, zip, txt');
                        $(this).val("");
                    }
                }
        });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil51200.onpageload' }); }
};

