scwin.editAttach = function (inputTagObj) {
    /* sdd-asis-lifecycle:begin editAttach — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const itemId = $(inputTagObj).attr("itemId");
    const itemObj = $("#" + itemId).get(0);
    const objIdx = Number(itemId.replace("docuItem", ""));
    if ($(itemObj).find("input[name='editYn']").is(":checked")) {
        $(itemObj).find("input[name='useYn']").removeAttr("disabled");
        $(itemObj).find("input[name='remk']").removeAttr("readonly");
        if ($(itemObj).find("input[name='useYn']").is(":checked")) {
            $(itemObj).find("#attachFiles" + objIdx).attr("disabled", true);
            if (objIdx >= $) {
                fn: length(formFileList);
            }
            $(itemObj).find("input[name='fileItmNm']").attr("readonly", true);
        } else {
            $(itemObj).find("#attachFiles" + objIdx).removeAttr("disabled");
            if (objIdx >= $) {
                fn: length(formFileList);
            }
            $(itemObj).find("input[name='fileItmNm']").removeAttr("readonly");
        }
    } else {
        $(itemObj).find("input[name='useYn']").attr("disabled", true);
        $(itemObj).find("input[name='remk']").attr("readonly", true);
        $(itemObj).find("#attachFiles" + objIdx).attr("disabled", true);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.doSave
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.doSave = async function () {
    /* sdd-asis-lifecycle:begin doSave — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let isFlag = true;
    const useYnObj = document.getElementsByName('useYn');
    const chkObj2 = document.getElementsByName('useYnApi');
    const editObj2 = document.getElementsByName('editYnApi');
    const itmObj2 = document.getElementsByName('fileItmNmApi');
    let fileObj2;
    for (let i = 0; i < chkObj2.length; i++) {
        if (((scwin.loadTp != 2 && scwin.loadTp != 3) || ((scwin.loadTp == 2 || scwin.loadTp == 3) && editObj2[i].checked)) && !chkObj2[i].checked) {
            fileObj2 = form['attachFilesApi['+i+']'];
            if (itmObj2[i].value === '') {
                await $c.win.alert("[기타 대용량 첨부서류] 첨부할 항목명을 입력하세요.");
                isFlag = false;
                break;
            } else {
                if (fileObj2.value === '') {
                    await $c.win.alert("[기타 대용량 첨부서류] 해당사항이 없는 경우 해당사항 없음을 체크하십시오.");
                    isFlag = false;
                    break;
                }
            }
        }
    }
    if (!isFlag) {
        return;
    }
    scwin.showSpinner();
    let url = '/listInvstg/lplAttach.do?method=savePreFiles';
    if (scwin.loadTp == 2 || scwin.loadTp == 3) {
        url = '/listInvstg/lplAttach.do?method=editPreFiles';
    }
    form.action = url;
    if (await scwin.checkValue()) {
        if (!await $c.win.confirm('저장하시겠습니까?')) {
            scwin.hideSpinner();
            return;
        }
        if (!await apiFileCheck()) {
            scwin.hideSpinner();
            return;
        }
        const editObj = document.getElementsByName('editYn');
        await moveUrl(url, {});
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkFileValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param idx
 * @returns
 * @hidden N
*/
scwin.checkFileValue = async function (idx) {
    /* sdd-asis-lifecycle:begin checkFileValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const chkObj = document.getElementsByName('useYn');
    const itemObj = document.getElementsByName('fileItmNm');
    let fileObj;
    let itmVal;
    if (chkObj[idx].checked !== true) {
        fileObj = form['attachFiles['+idx+']'];
        if (fileObj.value === '') {
            itmVal = itemObj[idx].value;
            itmVal = (itmVal === '' ? '기타' : itmVal);
            await $c.win.alert("[" + itmVal + ']항목에 대한 해당사항이 없는경우 해당사항 없음을 체크하십시오.');
            return false;
        }
        if (idx >= $) {
            fn: length(formFileList);
        }
        if (itemObj[idx].value === '') {
            await $c.win.alert("기타 첨부서류가 있는 경우 '항목명'까지 작성하셔야 합니다.");
            return false;
        }
        return true;
    } else {
        return true;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkFileYN
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkFileYN = async function () {
    /* sdd-asis-lifecycle:begin checkFileYN — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const chkObj = document.getElementsByName('useYn');
    const editObj = document.getElementsByName('editYn');
    if (scwin.loadTp == 2 || scwin.loadTp == 3) {
        for (var i = 0; i < chkObj.length; i++) {
            if (editObj[i].checked === true) {
                if (!await scwin.checkFileValue(i)) {
                    return false;
                }
            }
        }
    } else {
        for (var i = 0; i < chkObj.length; i++) {
            if (!await scwin.checkFileValue(i)) {
                return false;
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCBoxTrue
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.setCBoxTrue = function (ver) {
    /* sdd-asis-lifecycle:begin setCBoxTrue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const chkObj = document.getElementsByName(ver);
    let tORf = true;
    if (ver === 'editYn') {
        tORf = false;
    }
    for (let i = 0; i < chkObj.length; i++) {
        if (chkObj[i].checked === tORf) {
            chkObj[i].value = 'N';
        } else {
            chkObj[i].value = 'Y';
        }
        chkObj[i].checked = true;
    }
    /* sdd-asis-lifecycle:end */
};


