// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
/**
 * @method
 * @name scwin.getOtherDataDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.getOtherDataDone = function (data) {
    /* sdd-asis-lifecycle:begin fn_getOtherData_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    otherData = scwin.result.apiKey + '||' + scwin.result.integUsrId;
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.getOtherData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getOtherData = async function () {
    const r = await scwin.tx_fn_getOtherData();
    try {
        scwin.getOtherDataDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil51200.fn_getOtherData' });
    }
    return r;
};
